/// <reference types="vite/client" />

/**
 * Vite 环境变量类型定义
 */
interface ImportMetaEnv {

  // =========================================================
  // 🧩 应用基础信息（展示层）
  // =========================================================

  /**
   * 应用展示名称（UI显示用）
   * 例如：墓园业务系统 / CRM管理系统
   */
  readonly VITE_APP_TITLE: string

  // =========================================================
  // 🏗 系统标识（系统层）
  // =========================================================

  /**
   * 系统代码（用于区分不同系统）
   * 例如：admin-system / crm-system / uniapp-h5
   */
  readonly VITE_APP_CODE: string

  // =========================================================
  // 👤 租户信息（业务隔离层）
  // =========================================================

  /**
   * 租户ID（多租户系统核心标识）
   * 用于区分不同公司 / 机构 / 客户
   */
  readonly VITE_TENANT_ID: string

  // =========================================================
  // 🌐 API 配置（网络层）
  // =========================================================

  /**
   * API 基础请求地址
   * 例如：https://api.xxx.com
   */
  readonly VITE_API_BASE_URL: string

  /**
   * 开发环境代理目标地址
   * Vite proxy 使用
   */
  readonly VITE_API_PROXY_TARGET: string

  // =========================================================
  // 🧭 路由配置（前端运行层）
  // =========================================================

  /**
   * 路由模式
   * hash: 带 # 的路由
   * history: 普通路径模式
   */
  readonly VITE_APP_ROUTER_MODE: 'hash' | 'history' | 'memory'

  // =========================================================
  // 📦 平台标识（多端能力层）
  // =========================================================

  /**
   * 主进程账号
   */
  readonly MAIN_VITE_PLATFORM_ACCOUNT: string

  /**
   * 主进程密码
   */
  readonly MAIN_VITE_PLATFORM_PASSWORD: string

  /**
   * 主进程 API 基础请求地址
   * 例如：https://api.xxx.com
   */
  readonly MAIN_VITE_PLATFORM_API_BASE_URL: string

  // =========================================================
  // 📁 静态资源配置
  // =========================================================

  /**
   * 静态资源公共路径
   * 必须以 / 开头并以 / 结尾
   * 例如：/static/
   */
  readonly VITE_APP_PUBLIC_PATH: string

}

/**
 * Vite 环境变量扩展
 */
interface ImportMeta {
  readonly env: ImportMetaEnv
}
